var minuteur;

document.getElementById("rech").addEventListener("input", function () {
  clearTimeout(minuteur);
  var q = this.value;

  minuteur = setTimeout(async function () {
    try {
      var res = await fetch("search.php?q=" + encodeURIComponent(q));
      if (!res.ok) throw new Error("Erreur HTTP " + res.status);
      var data = await res.json();

      var div = document.getElementById("liste");
      div.innerHTML = "";
      data.forEach(function (p) {
        var el = document.createElement("p");
        el.textContent = p.nom + " " + p.prenom;
        div.appendChild(el);
      });
    } catch (err) {
      document.getElementById("liste").textContent = "Erreur : " + err.message;
    }
  }, 300);
});
